$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT LocationCode FROM WicLocations WHERE DisplayName='Essen - TK'"; $code=$cmd.ExecuteScalar(); Write-Host "Code:" $code; $cmd2=$conn.CreateCommand(); $cmd2.CommandText="SELECT EmployeeName FROM WicAgentAssignments WHERE LocationCode LIKE '%Essen%' AND AssignmentType='MAIN'"; $r=$cmd2.ExecuteReader(); while($r.Read()){Write-Host "Main:" $r[0]}; $conn.Close()
